package protobuflog_test

import (
	"bytes"
	"encoding/binary"
	"os"
	"testing"

	"github.com/egdaemon/eg/internal/protobuflog"
	"github.com/stretchr/testify/require"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/descriptorpb"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestEncoderEncode(t *testing.T) {
	t.Run("encodes a single message with 8-byte little-endian length prefix", func(t *testing.T) {
		buf := &bytes.Buffer{}
		enc := protobuflog.NewEncoder[*descriptorpb.FileDescriptorProto](buf)

		msg := &descriptorpb.FileDescriptorProto{Name: proto.String("hello")}
		require.NoError(t, enc.Encode(msg))

		marshalled, err := proto.Marshal(msg)
		require.NoError(t, err)

		var lengthPrefix [8]byte
		binary.LittleEndian.PutUint64(lengthPrefix[:], uint64(len(marshalled)))
		want := append(lengthPrefix[:], marshalled...)

		require.Equal(t, want, buf.Bytes())
	})

	t.Run("encodes multiple messages sequentially", func(t *testing.T) {
		buf := &bytes.Buffer{}
		enc := protobuflog.NewEncoder[*descriptorpb.FileDescriptorProto](buf)

		msgs := []*descriptorpb.FileDescriptorProto{
			{Name: proto.String("a")},
			{Name: proto.String("b")},
			{Name: proto.String("c")},
		}
		require.NoError(t, enc.Encode(msgs...))

		var expected []byte
		for i := range msgs {
			b, err := proto.Marshal(msgs[i])
			require.NoError(t, err)
			var lp [8]byte
			binary.LittleEndian.PutUint64(lp[:], uint64(len(b)))
			expected = append(expected, lp[:]...)
			expected = append(expected, b...)
		}

		require.Equal(t, expected, buf.Bytes())
	})

	t.Run("roundtrip through decoder preserves content", func(t *testing.T) {
		buf := &bytes.Buffer{}
		enc := protobuflog.NewEncoder[*descriptorpb.FileDescriptorProto](buf)

		msgs := []*descriptorpb.FileDescriptorProto{
			{Name: proto.String("one")},
			{Name: proto.String("two")},
			{Name: proto.String("three")},
		}
		require.NoError(t, enc.Encode(msgs...))

		dec := protobuflog.NewDecoder[*descriptorpb.FileDescriptorProto](buf)
		decoded := make([]*descriptorpb.FileDescriptorProto, 0, 3)
		require.NoError(t, dec.Decode(&decoded))

		require.Len(t, decoded, 3)
		require.Equal(t, "one", decoded[0].GetName())
		require.Equal(t, "two", decoded[1].GetName())
		require.Equal(t, "three", decoded[2].GetName())
	})

	t.Run("encodes zero messages without error or output", func(t *testing.T) {
		buf := &bytes.Buffer{}
		enc := protobuflog.NewEncoder[*descriptorpb.FileDescriptorProto](buf)

		require.NoError(t, enc.Encode())
		require.Empty(t, buf.Bytes())
	})

	t.Run("reports write error", func(t *testing.T) {
		f, err := os.CreateTemp(t.TempDir(), "")
		require.NoError(t, err)
		require.NoError(t, f.Close())

		enc := protobuflog.NewEncoder[*descriptorpb.FileDescriptorProto](f)
		err = enc.Encode(&descriptorpb.FileDescriptorProto{Name: proto.String("x")})
		require.Error(t, err)
	})
}
